# Adds the old-newspaper pins (nw-) to og-data.js; rerunning replaces them. usage: patch_nw.py og-data.js
import json,re,sys
f=sys.argv[1]; d=open(f,encoding='utf-8').read()
CA='Chronicling America (Library of Congress), '
