d=re.sub(r'\n// newspaper pins \(nw-\)[^\n]*\nDATA\.points\.push\([^\n]*\n','\n',d)
d=d.rstrip('\n')+'\n// newspaper pins (nw-): Chronicling America leads, River Falls/Prescott/Ladysmith papers\nDATA.points.push('+','.join(json.dumps(p,ensure_ascii=False,separators=(',',':')) for p in P)+');\n'
